@@ -420,0 +420,16 @@
+instruct addL_reg_reg_and_uxtw_b(iRegLNoSp dst, iRegL src1, iRegL src2, immL_32bits mask) %{
+  predicate(UseZba);
+  match(Set dst (AddL src1 (AndL src2 mask)));
+
+  ins_cost(ALU_COST);
+  format %{ "add.uw $dst, $src2, $src1\t#@addL_reg_reg_and_uxtw_b" %}
+
+  ins_encode %{
+    __ add_uw(as_Register($dst$$reg),
+              as_Register($src2$$reg),
+              as_Register($src1$$reg));
+  %}
+
+  ins_pipe(ialu_reg_reg);
+%}
+
@@ -437,0 +453,17 @@
+instruct shaddL_reg_reg_and_uxtw_b(iRegLNoSp dst, iRegL src1, iRegL src2, immL_32bits mask, immIScale imm) %{
+  predicate(UseZba);
+  match(Set dst (AddL src1 (LShiftL (AndL src2 mask) imm)));
+
+  ins_cost(ALU_COST);
+  format %{ "shadd.uw $dst, $src2, $src1, $imm\t#@shaddL_reg_reg_and_uxtw_b" %}
+
+  ins_encode %{
+    __ shadd_uw(as_Register($dst$$reg),
+                as_Register($src2$$reg),
+                as_Register($src1$$reg),
+                $imm$$constant);
+  %}
+
+  ins_pipe(ialu_reg_reg);
+%}
+

